use lito_modern::modern_lito::native_room::{self,EarlyRoster,Packet};
fn fixture()->(native_room::Room,u32,native_room::Member){let v:serde_json::Value=serde_json::from_slice(include_bytes!("fixtures/native-early-roster.json")).unwrap();let bytes=|k:&str|{let s=v["packets"][k].as_str().unwrap();(0..s.len()).step_by(2).map(|i|u8::from_str_radix(&s[i..i+2],16).unwrap()).collect::<Vec<_>>()};let Packet::Joined(r)=native_room::parse(&bytes("joined")).unwrap() else {panic!()};let Packet::Member{room,member}=native_room::parse(&bytes("member")).unwrap() else {panic!()};(r,room,member)}
#[test]
fn captured_early_members_wait_for_matching_acceptance_and_latest_snapshot_wins(){let (mut r,id,mut m)=fixture();assert_eq!(r.id,id);let mut p=EarlyRoster::default();p.push(4,Some(id),id,m.clone()).unwrap();assert!(r.members.is_empty());m.force=1;p.push(4,Some(id),id,m.clone()).unwrap();let rows=p.take(4,id).unwrap();assert_eq!(rows.len(),1);assert_eq!(rows[0].force,1);for member in rows{native_room::upsert(&mut r,member).unwrap();}assert_eq!(r.members[0].name,m.name);assert!(p.take(4,id).unwrap().is_empty());}
#[test]
fn pending_roster_cannot_cross_connection_room_rejection_or_new_request(){let (_,id,m)=fixture();let mut p=EarlyRoster::default();assert!(p.push(4,Some(id+1),id,m.clone()).is_err());p.push(4,Some(id),id,m.clone()).unwrap();assert!(p.take(5,id).is_err());assert!(p.take(4,id+1).is_err());assert!(p.push(5,Some(id),id,m.clone()).is_err());p.clear();assert!(p.take(5,id+1).unwrap().is_empty());p.push(5,None,id+1,m).unwrap();assert!(p.take(5,id).is_err());assert_eq!(p.take(5,id+1).unwrap().len(),1);}
#[test]
fn pending_roster_preserves_wire_order_and_existing_256_member_bound(){let (_,id,m)=fixture();let mut p=EarlyRoster::default();for i in 0..256{let mut row=m.clone();row.name=format!("member{i}");p.push(4,Some(id),id,row).unwrap();}let mut extra=m.clone();extra.name="overflow".into();assert!(p.push(4,Some(id),id,extra).is_err());let rows=p.take(4,id).unwrap();assert_eq!(rows[0].name,"member0");assert_eq!(rows[255].name,"member255");}
